window.__votdWeek && window.__votdWeek({"week":"2029-04-16","reading":"Doctrine and Covenants 30–36","days":[{"d":"2029-04-16","ref":"D&C 31:5","b":"D&C","c":31,"v":5,"he":"לָכֵן שְׁלַח מַגָּלְךָ בְּכׇל־נַפְשְׁךָ וְחַטֹּאתֶיךָ נִסְלְחוּ לְךָ וְנָשָׂאתָ אֲלֻמּוֹת עַל־שִׁכְמְךָ כִּי שֹׁוֶה הַפֹּעֵל בִּשְׂכָרוֹ עַל־כֵּן תִּחְיֶה מִשְׁפַּחְתְּךָ׃","en":"Therefore, thrust in your sickle with all your soul, and your sins are forgiven you, and you shall be laden with sheaves upon your back, for the laborer is worthy of his hire. Wherefore, your family shall live."},{"d":"2029-04-17","ref":"D&C 33:3","b":"D&C","c":33,"v":3,"he":"כִּי הִנֵּה הַשָּׂדֶה כְּבָר הִלְבִּין לַקָּצִיר וְזֹאת הַשָּׁעָה הָאַחַת־עֶשְׂרֵה וְהַפַּעַם הָאַחֲרוֹנָה אֲשֶׁר אֶקְרָא פֹעֲלִים אֶל כַּרְמִי׃","en":"For behold, the field is white already to harvest; and it is the eleventh hour, and the last time that I shall call laborers into my vineyard."},{"d":"2029-04-18","ref":"D&C 33:4","b":"D&C","c":33,"v":4,"he":"וְכַרְמִי הֻשְׁחַת כֻּלּוֹ וְאֵין עֹשֵׂה טוֹב זוּלָתִי מְעַטִּים וְהֵם תֹּעִים בִּדְבָרִים רַבִּים מִפְּנֵי כְּהֻנַּת־שָׁוְא וְכֻלָּם נִשְׁחָתִים בְּדַעְתָּם׃","en":"And my vineyard has become corrupted every whit; and there is none which doeth good save it be a few; and they err in many instances because of priestcrafts, all having corrupt minds."},{"d":"2029-04-19","ref":"D&C 34:7","b":"D&C","c":34,"v":7,"he":"כִּי הִנֵּה אָמֵן אָמֵן אֲנִי אֹמֵר לְךָ בִּמְהֵרָה קׇרְבָה הָעֵת אֲשֶׁר אָבוֹא בְּעָנָן בְּכֹחַ וּבְכָבוֹד גָּדוֹל׃","en":"For behold, verily, verily, I say unto you, the time is soon at hand that I shall come in a cloud with power and great glory."},{"d":"2029-04-20","ref":"D&C 34:8","b":"D&C","c":34,"v":8,"he":"וְהָיָה יוֹם גָּדוֹל בְּעֵת בּוֹאִי כִּי כׇל הַגּוֹיִם יֶחֱרָדוּ׃","en":"And it shall be a great day at the time of my coming, for all nations shall tremble."},{"d":"2029-04-21","ref":"D&C 35:4","b":"D&C","c":35,"v":4,"he":"בָּרוּךְ אַתָּה כִּי דְבָרִים גְּדוֹלִים תַּעֲשֶׂה הִנֵּה נִשְׁלַחְתָּ כְּיוֹחָנָן לְפַנּוֹת הַדֶּרֶךְ לְפָנַי וְלִפְנֵי אֵלִיָּהוּ אֲשֶׁר יָבוֹא וְלֹא יָדָעְתָּ׃","en":"Thou art blessed, for thou shalt do great things. Behold thou wast sent forth, even as John, to prepare the way before me, and before Elijah which should come, and thou knewest it not."},{"d":"2029-04-22","ref":"D&C 35:25","b":"D&C","c":35,"v":25,"he":"וְיִשְׂרָאֵל יִוָּשַׁע בְּעִתִּי וּבַמַּפְתְּחוֹת אֲשֶׁר נָתַתִּי יִנָּהֲגוּ וְלֹא יִכָּלְמוּ עוֹד׃","en":"And Israel shall be saved in mine own due time; and by the keys which I have given shall they be led, and no more be confounded at all."}]});
